children.text:
html,body {
  margin: 0;
}

.outer {
  writing-mode: vertical-lr;
  display: inline-block;
}

.outer * {
  border: 2px solid lime;
  display: inline-block;
}

.container {
  height: 80px;
  border-color: blue;
  vertical-align: bottom;

  font-family: Ahem;
  font-size: 8px;
  line-height: 13px;
}

.too-small {
  width: 10px;
}

.too-big {
  width: 100px;
}
